/**
 * Aqua 旧集中流动性策略解析回归测试。
 * 核心功能：用已确认的真实 strategyBytes 验证 SDK 解码出唯一集中流动性指令和相邻 raw 价格范围。
 * 主要流程：解析历史策略字节 -> 读取 raw 区间 -> 断言区间有效且落在创建记录附近。
 */
import { expect, test } from "bun:test";
import { parseConcentratedRawRange } from "../src/aqua/strategy-parser.ts";

const strategyBytes = "" as const;

test("解析真实集中流动性 strategyBytes 的 raw 价格范围", () => {
  const range = parseConcentratedRawRange(strategyBytes);
  // sqrt price 向下取整，所以平方回转允许比创建入参少不足 1 raw 单位。
  expect(range.rawPriceMin).toBe(23203668188033079n);
  expect(range.rawPriceMax).toBe(23205988786911771n);
});
